use stable.herd;
use stable.ledger;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    var output = "";
    var first = true;

    for pony in herd.lineup() {
        let fed = herd.feed(pony: pony, scoops: 3);
        let entry = ledger.render(pony: fed);
        if first {
            output = entry;
            first = false;
        } else {
            output = output.concat(other: ",").concat(other: entry);
        }
    }

    io.write(text: output)?;
    return Ok(unit);
}

