use mill.stock;
use mill.rules;

pub fn lines() -> String {
    var result = "";
    var first = true;

    for plank in stock.inventory() {
        if rules.keep(plank: plank) {
            if first {
                result = rules.label(plank: plank);
                first = false;
            } else {
                result = result.concat(other: ",").concat(other: rules.label(plank: plank));
            }
        }
    }

    result
}

